head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[session > M > removeSession]<br/>브라우저 세션 데이터 전체를 삭제합니다.",
    "validation" : [        
        "브라우저 세션 데이터 전체를 삭제해야 합니다.",
        "프레임이나 팝업 윈도우에서 호출해도 모든 윈도우의 세션 데이터가 삭제되어야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 세션 여러 키 사전 등록
scwin.setupSession = function () {
    WebSquare.session.setAttribute("key1", "value1");
    WebSquare.session.setAttribute("key2", "value2");
    WebSquare.session.setAttribute("key3", "value3");
};



scwin.btn_removeSession_onclick = function () {
    scwin.setupSession();

    wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : 세션 데이터 전체 삭제 ──");
    wf_body_bottom.getObj("scwin").setReturnValue("삭제 전 key1='" + WebSquare.session.getAttribute("key1") + "', key2='" + WebSquare.session.getAttribute("key2") + "', key3='" + WebSquare.session.getAttribute("key3") + "'");

    WebSquare.session.removeSession();

    wf_body_bottom.getObj("scwin").setReturnValue("삭제 후 key1=" + WebSquare.session.getAttribute("key1") + ", key2=" + WebSquare.session.getAttribute("key2") + ", key3=" + WebSquare.session.getAttribute("key3"));
};



scwin.btn_removeFromPopup_onclick = function () {
    scwin.setupSession();

    wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : 팝업에서 removeSession 호출 → 메인 윈도우 세션도 삭제 ──");
    wf_body_bottom.getObj("scwin").setReturnValue("삭제 전 key1='" + WebSquare.session.getAttribute("key1") + "', key2='" + WebSquare.session.getAttribute("key2") + "', key3='" + WebSquare.session.getAttribute("key3") + "'");
    wf_body_bottom.getObj("scwin").setReturnValue("팝업 내부에서 removeSession 호출 후, 팝업 닫고 [메인 세션 확인] 버튼 클릭");

    $p.openPopup("/sample/common_link/session_removeSession_popup.xml", {
        id: "removeSession_popup",
        type: "wframePopup",
        width: "500px",
        height: "300px",
        top: "100px",
        left: "100px",
        popupName: "removeSession 팝업",
        modal: false
    });
};



scwin.btn_checkMainSession_onclick = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("── 메인 세션 확인 (팝업에서 removeSession 후) ──");
    wf_body_bottom.getObj("scwin").setReturnValue("key1=" + WebSquare.session.getAttribute("key1") + ", key2=" + WebSquare.session.getAttribute("key2") + ", key3=" + WebSquare.session.getAttribute("key3"));
};
